/**
 * Return the DNS records a customer must publish at their registrar for an
 * EXTERNAL domain so mail flows through the Nxeon mail server, plus the
 * ownership-verification record. Ownership-checked (caller must own the sub).
 *
 * The DKIM record is fetched from Mailcow (`mcGetDkim`) and cached in
 * `dkimRecord`; when Mailcow isn't configured (or has no key yet) a placeholder
 * note is returned so the panel still renders.
 */
export async function getEmailDnsRecords(
  subscriptionId: string,
): Promise<{
  error?: string;
  records?: DnsRecord[];
  verified?: boolean;
  external?: boolean;
  cloudflareConnected?: boolean;
}> {
  const user = await requireUser();

  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
  if (!sub) return { error: "Subscription not found." };
  if (sub.userId !== user.id) return { error: "Not your subscription." };

  const domain = sub.domainName;

  // Resolve the DKIM TXT: prefer the cached value, else fetch + cache from Mailcow.
  let dkimTxt = sub.dkimRecord ?? null;
  if (!dkimTxt && mailcowConfigured()) {
    try {
      // Ensure the mail domain exists so Mailcow has generated a DKIM key.
      if (!(await mcDomainExists(domain))) {
        await mcCreateDomain(domain).catch(() => {});
      }
      dkimTxt = await mcGetDkim(domain);
      if (dkimTxt) {
        await db.emailSubscription
          .update({ where: { id: sub.id }, data: { dkimRecord: dkimTxt } })
          .catch(() => {});
      }
    } catch (e) {
      console.warn(`[mailcow] get dkim ${domain} failed:`, e);
    }
  }

  const records: DnsRecord[] = [
    {
      type: "TXT",
      label: "Ownership verification",
      host: `_nxeon-verify.${domain}`,
      value: `nxeon-verify=${sub.verifyToken ?? ""}`,
      note: "Proves you control this domain. Required before mail is enabled.",
    },
    {
      type: "MX",
      label: "Mail routing (MX)",
      host: domain,
      value: MAIL_HOST,
      priority: MAIL_MX_PRIORITY,
    },
    {
      type: "TXT",
      label: "SPF",
      host: domain,
      value: SPF_VALUE,
      note: "Authorizes the Nxeon mail server to send for your domain.",
    },
    {
      type: "TXT",
      label: "DKIM",
      host: `${DKIM_SELECTOR}._domainkey.${domain}`,
      value: dkimTxt ?? "",
      note: dkimTxt
        ? undefined
        : "DKIM key is being generated on the mail server — refresh this page shortly to see the value.",
    },
    {
      type: "TXT",
      label: "DMARC",
      host: `_dmarc.${domain}`,
      value: DMARC_VALUE,
      note: "Reporting policy for messages that fail SPF/DKIM.",
    },
  ];

  return {
    records,
    verified: sub.verified,
    external: sub.external,
    // True for either connection shape (OAuth credentials or a legacy token).
    cloudflareConnected: readStoredCloudflare(user.cloudflareTokenEnc) !== null,
  };
}

