  const hostnameValid = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i.test(hostname) && hostname.length >= 3;
  const planMeetsImage = !!plan && !!image && plan.ramMB >= image.minRamMB && plan.diskGB >= image.minDiskGB;
  const ipMonthly = dedicatedIp ? dedicatedIpPriceCents ?? 0 : 0;
  // Extra root disk: per-GB/month × GB, then × the term — priced exactly like the
  // dedicated IP (no term discount, no promo), matching lib/order.ts orderQuote.
  const extraDiskOffered = (extraDiskPriceCentsPerGb ?? 0) > 0;
  const extraDiskMonthly = extraDiskCentsAt(extraDiskGB, extraDiskPriceCentsPerGb ?? 0);
  const totalDiskGB = plan ? effectiveDiskGB(plan.diskGB, extraDiskGB) : 0;
  // Regular (renewal) plan price for the chosen term, and the promo-discounted
  // first-term price actually charged. The dedicated IP is billed at full price.
  const regularPlanTerm = plan ? vpsTermPriceCents(plan.priceCents, termMonths) : 0;
  const promoPlanTerm = promoCents(regularPlanTerm);
  const addonTermCents = (ipMonthly + extraDiskMonthly) * termMonths;
  const dueCents = free ? 0 : plan ? promoPlanTerm + addonTermCents : 0;
  const regularDueCents = free ? 0 : plan ? regularPlanTerm + addonTermCents : 0;
  // Exact wallet/card split — identical math to lib/actions.ts payAndDeploy, so
  // the numbers shown here are byte-for-byte what gets charged.
  const split = walletSplit({ dueCents, balanceCents, useWallet });
  const walletApplied = split.walletApplied;
  const cardCents = split.cardCents;
  const canDeploy = !!planId && !!imageId && hostnameValid && planMeetsImage;
  const isLast = step === steps.length - 1;
  const curLabel = steps[step];

  return (
    <form
      action={action}
      // The whole wizard is one form, so a stray Enter in a text field (e.g. the
      // hostname input) would implicitly submit it — deploying immediately with
      // the default term and skipping the Review step. Block implicit submission
      // everywhere except the final Review step; Enter still works in textareas
      // (the SSH-key field). Deploy only ever happens via the explicit button.
      onKeyDown={(e) => {
        if (e.key === "Enter" && (e.target as HTMLElement).tagName !== "TEXTAREA") {
          // Block implicit Enter-submit everywhere but the final Review step. On the
          // final step Enter is allowed to submit — arm the redirect flag so it is
          // treated exactly like an explicit Deploy click.
          if (!isLast) e.preventDefault();
          else submittedRef.current = true;
