      <input type="hidden" name="addon_backup" value={addons.backup ? "1" : "0"} />
      <input type="hidden" name="addon_docker" value={addons.docker ? "1" : "0"} />
      <input type="hidden" name="dedicatedIp" value={dedicatedIp ? "1" : "0"} />
      <input type="hidden" name="extraDiskGB" value={extraDiskGB} />
      {pubKey.trim() && <input type="hidden" name="sshPublicKey" value={pubKey.trim()} />}
      {isAdmin && free && <input type="hidden" name="free" value="1" />}
      <input type="hidden" name="termMonths" value={termMonths} />
      <input type="hidden" name="useWallet" value={useWallet ? "1" : "0"} />

      <div className="card">
        <Stepper step={step} steps={steps} />
        {state?.error && (
          <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{state.error}</div>
        )}

        {curLabel === "Plan" && (
          <div>
            <h2 className="mb-4 font-semibold">Choose your resources</h2>
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {plans.map((p, i) => (
                <button type="button" key={p.id} onClick={() => setPlanId(p.id)}
                  className={`card p-4 text-left transition ${planId === p.id ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"}`}>

