/**
 * "Finish setup" panel for an EXTERNAL, unverified email subscription. Lazily
 * loads the DNS records (server-side, ownership-checked), renders each with copy
 * buttons, and runs DNS verification. The verified result is decided entirely by
 * the server action — this component only reflects it.
 */
export function EmailDnsSetup({
  subscriptionId,
  domainName,
  verified: initialVerified,
}: {
  subscriptionId: string;
  domainName: string;
  verified: boolean;
}) {
  const [records, setRecords] = useState<DnsRecord[] | null>(null);
  const [verified, setVerified] = useState(initialVerified);
  const [error, setError] = useState<string | null>(null);
  const [status, setStatus] = useState<string | null>(null);
  const [loading, startLoad] = useTransition();
  const [verifying, startVerify] = useTransition();
  const [open, setOpen] = useState(false);
  const [cfConnected, setCfConnected] = useState(false);

  function load() {
    setError(null);
    startLoad(async () => {
      const res = await getEmailDnsRecords(subscriptionId);
      if (res?.error) {
        setError(res.error);
        return;
      }
      setRecords(res.records ?? []);
      if (typeof res.verified === "boolean") setVerified(res.verified);
      if (typeof res.cloudflareConnected === "boolean") setCfConnected(res.cloudflareConnected);
      setOpen(true);
    });
  }

  function verify() {
    setError(null);
    setStatus(null);
    startVerify(async () => {
      const res = await verifyEmailDomain(subscriptionId);
      if (res?.error) {
        setError(res.error);
      } else if (res?.ok) {
        setVerified(true);
        setStatus("DNS verified — mail is now enabled for this domain.");
      }
    });
  }

