function WhoisPrivacySection({
  domainId,
  initial,
}: {
  domainId: string;
  initial: boolean;
}) {
  const router = useRouter();
  const [enabled, setEnabled] = useState(initial);
  const [note, setNote] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  function toggle() {
    const next = !enabled;
    setEnabled(next); // optimistic
    start(async () => {
      setError(null);
      setNote(null);
      const res = await setWhoisPrivacy(domainId, next);
      if (res?.error) {
        setEnabled(!next);
        setError(res.error);
      } else {
        setNote(res.note ?? "Saved.");
        router.refresh();
      }
    });
  }

  return (
    <div className="card">
      <div className="mb-1 flex items-center justify-between">
        <h2 className="font-semibold">WHOIS privacy</h2>
        <button
          type="button"
          disabled={pending}
          onClick={toggle}
          title={enabled ? "Privacy on — click to turn off" : "Privacy off — click to turn on"}
          className={`relative h-5 w-9 cursor-pointer rounded-full transition-colors disabled:opacity-50 ${
            enabled ? "bg-gradient-to-r from-accent-blue to-brand-500" : "bg-white/10"
