          />
        </button>
      </div>
      <p className="text-sm text-slate-400">
        When on, your personal contact details are hidden from the public WHOIS directory and
        replaced with privacy-protection contacts.
      </p>
      <p className="mt-2 text-xs text-slate-500">
        Currently <span className="font-medium text-slate-300">{enabled ? "on" : "off"}</span>.
